blixis-base/assets/src/tailwind.css:
/* Blixis Base utilities. Source of truth for names: docs/contracts/tokens/v1/golden/tailwind.css.
   Utilities only: no preflight, no layer, no dynamic scanning of stored content. */
@import "tailwindcss/utilities.css" source(none);

/* Known template sources and the approved static safelist only. */
@source "../../templates";
@source "../../parts";
@source "../../patterns";
@source "./safelist.html";

.wp-site-blocks header .wp-block-page-list {
  display: flex;
  flex-wrap: wrap;
  gap: var(--blixis-spacing-sm, 0.5rem);
  list-style: none;
  padding-inline-start: 0;
}
/* Neutral template safeguards, also loaded in the editor. */
.wp-site-blocks {
  padding-inline: var(--blixis-spacing-md, 1rem);
  overflow-wrap: anywhere;
}
.wp-site-blocks > * + * {
  margin-block-start: var(--blixis-spacing-lg, 2rem);
}
.wp-block-page-list a,
.wp-block-post-terms a,
.wp-block-navigation a,
.wp-block-query-pagination a,
.wp-block-query-pagination .page-numbers,
.wp-block-post-navigation-link a {
  display: inline-flex;
  align-items: center;
  min-block-size: 24px;
  min-inline-size: 24px;
}
.wp-site-blocks :is(a, button, input, select, textarea, summary, [tabindex]):focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 3px;
}

@theme {
  --*: initial;
  --breakpoint-sm: 40rem;
  --breakpoint-md: 48rem;
  --breakpoint-lg: 64rem;
  --breakpoint-xl: 80rem;
}

@theme inline {
  --color-primary: var(--blixis-color-primary);
  --color-surface: var(--blixis-color-surface);
  --color-foreground: var(--blixis-color-foreground);
  --color-muted: var(--blixis-color-muted);
  --color-accent: var(--blixis-color-accent);
  --font-body: var(--blixis-font-body);
  --font-heading: var(--blixis-font-heading);
  --font-mono: var(--blixis-font-mono);
  --text-xs: var(--blixis-text-xs);
  --text-sm: var(--blixis-text-sm);
  --text-base: var(--blixis-text-base);
  --text-lg: var(--blixis-text-lg);
  --text-xl: var(--blixis-text-xl);
  --text-2xl: var(--blixis-text-2xl);
  --text-3xl: var(--blixis-text-3xl);
  --spacing-xs: var(--blixis-spacing-xs);
  --spacing-sm: var(--blixis-spacing-sm);
  --spacing-md: var(--blixis-spacing-md);
  --spacing-lg: var(--blixis-spacing-lg);
  --spacing-xl: var(--blixis-spacing-xl);
  --radius-sm: var(--blixis-radius-sm);
  --radius-md: var(--blixis-radius-md);
  --radius-lg: var(--blixis-radius-lg);
  --shadow-sm: var(--blixis-shadow-sm);
  --shadow-md: var(--blixis-shadow-md);
  --shadow-lg: var(--blixis-shadow-lg);
}

blixis-base/package.json:
{
  "name": "blixis-base-theme",
  "version": "0.0.0",
  "private": true,
  "description": "Blixis Base parent theme asset pipeline. Compiled CSS is committed; WordPress hosts need no Node.",
  "license": "GPL-2.0-or-later",
  "type": "module",
  "scripts": {
    "clean": "rm -f assets/build/tailwind.css",
    "build:css": "tailwindcss --input assets/src/tailwind.css --output assets/build/tailwind.css --minify",
    "build": "pnpm run clean && pnpm run build:css"
  },
  "devDependencies": {
    "@tailwindcss/cli": "4.3.5",
    "tailwindcss": "4.3.5"
  }
}

blixis-base/theme.json:
{
  "$schema": "https://schemas.wp.org/trunk/theme.json",
  "version": 3,
  "templateParts": [
    { "name": "header", "area": "header" },
    { "name": "footer", "area": "footer" }
  ],
  "settings": {
    "border": {
      "radiusSizes": [
        { "name": "Sm", "size": "0.375rem", "slug": "sm" },
        { "name": "Md", "size": "0.75rem", "slug": "md" },
        { "name": "Lg", "size": "1.25rem", "slug": "lg" }
      ]
    },
    "color": {
      "defaultPalette": false,
      "palette": [
        { "color": "#155dfc", "name": "Primary", "slug": "primary" },
        { "color": "#ffffff", "name": "Surface", "slug": "surface" },
        { "color": "#101828", "name": "Foreground", "slug": "foreground" },
        { "color": "#64748b", "name": "Muted", "slug": "muted" },
        { "color": "#06b6d4", "name": "Accent", "slug": "accent" }
      ]
    },
    "custom": {
      "blixis": {
        "layout": { "gutter": "1.5rem" },
        "motion": {
          "durationBase": "200ms",
          "durationFast": "120ms",
          "durationSlow": "320ms",
          "easing": "cubic-bezier(0.4, 0, 0.2, 1)"
        }
      }
    },
    "layout": { "contentSize": "42rem", "wideSize": "72rem" },
    "shadow": {
      "defaultPresets": false,
      "presets": [
        { "name": "Sm", "shadow": "0 1px 2px 0 #0000001a", "slug": "sm" },
        { "name": "Md", "shadow": "0 4px 6px -1px #0000001a, 0 2px 4px -2px #0000001a", "slug": "md" },
        { "name": "Lg", "shadow": "none", "slug": "lg" }
      ]
    },
    "spacing": {
      "defaultSpacingSizes": false,
      "spacingSizes": [
        { "name": "Xs", "size": "0.5rem", "slug": "xs" },
        { "name": "Sm", "size": "0.75rem", "slug": "sm" },
        { "name": "Md", "size": "1rem", "slug": "md" },
        { "name": "Lg", "size": "1.5rem", "slug": "lg" },
        { "name": "Xl", "size": "2.5rem", "slug": "xl" }
      ]
    },
    "typography": {
      "defaultFontSizes": false,
      "fontFamilies": [
        { "fontFamily": "system-ui", "name": "Body", "slug": "body" },
        { "fontFamily": "system-ui", "name": "Heading", "slug": "heading" },
        { "fontFamily": "ui-monospace", "name": "Mono", "slug": "mono" }
      ],
      "fontSizes": [
        { "fluid": false, "name": "Xs", "size": "0.75rem", "slug": "xs" },
        { "fluid": false, "name": "Sm", "size": "0.875rem", "slug": "sm" },
        { "fluid": false, "name": "Base", "size": "1rem", "slug": "base" },
        { "fluid": false, "name": "Lg", "size": "1.125rem", "slug": "lg" },
        { "fluid": false, "name": "Xl", "size": "1.25rem", "slug": "xl" },
        { "fluid": false, "name": "2xl", "size": "1.5rem", "slug": "2xl" },
        { "fluid": false, "name": "3xl", "size": "2rem", "slug": "3xl" }
      ]
    }
  },
  "styles": {
    "color": {
      "background": "var:preset|color|surface",
      "text": "var:preset|color|foreground"
    },
    "typography": {
      "fontFamily": "var:preset|font-family|body",
      "fontSize": "var:preset|font-size|base",
      "lineHeight": "1.6"
    },
    "spacing": { "blockGap": "var:preset|spacing|md" },
    "elements": {
      "heading": {
        "color": { "text": "var:preset|color|foreground" },
        "typography": { "fontFamily": "var:preset|font-family|heading", "fontWeight": "700", "lineHeight": "1.15" }
      },
      "link": {
        "color": { "text": "var:preset|color|primary" },
        "typography": { "textDecoration": "underline" },
        ":hover": { "color": { "text": "var:preset|color|accent" } },
        ":focus": { "color": { "text": "var:preset|color|primary" } }
      },
      "button": {
        "color": { "background": "var:preset|color|primary", "text": "var:preset|color|surface" },
        "border": { "radius": "var:preset|border-radius|sm" },
        "spacing": { "padding": { "top": "var:preset|spacing|sm", "bottom": "var:preset|spacing|sm", "left": "var:preset|spacing|md", "right": "var:preset|spacing|md" } },
        ":hover": { "color": { "background": "var:preset|color|accent" } },
        ":focus": { "outline": { "color": "var:preset|color|primary", "style": "solid", "width": "2px" } }
      }
    },
    "blocks": {
      "core/post-content": { "spacing": { "blockGap": "var:preset|spacing|md" } },
      "core/group": { "spacing": { "blockGap": "var:preset|spacing|md" } }
    }
  }
}
